using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Reflection;using System.Threading;
namespace Frociart.Tests {internal static class FlowHomeTests {
static int count;const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
static void Check(bool value,string why){if(!value)throw new Exception(why);count++;Console.WriteLine("PASS "+why);}
static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,F).Invoke(o,args);}
static T Field<T>(object o,string name){return(T)o.GetType().GetField(name,F).GetValue(o);}
static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control child in c.Controls)foreach(Control nested in Walk(child))yield return nested;}
static void Pump(){var end=DateTime.UtcNow.AddMilliseconds(420);do{Application.DoEvents();Thread.Sleep(4);}while(DateTime.UtcNow<end);}
[STAThread]static int Main(){try{Application.EnableVisualStyles();string data=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"home-isolated-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(data);Environment.SetEnvironmentVariable("FROCIART_DATA_DIR",data);
Check(RecentProjects.Read().Length==0,"Empty history does not scan real user files in test mode");string a=Path.Combine(data,"Primo.frociart"),b=Path.Combine(data,"Secondo.flow");var first=FlowPseudocode.Decode("STAMPA 12");first.Title="Primo";DiagramIO.Save(a,first);var second=FlowPseudocode.Decode("LEGGI eta");second.Title="Secondo";DiagramIO.Save(b,second);
using(var f=new MainForm(null,true)){f.ShowInTaskbar=false;f.Location=new Point(-3000,-3000);f.Size=new Size(1120,720);f.Show();Pump();Check(Field<Control>(f,"homePanel").Visible,"Starts on flowchart home");Check(Walk(f).Any(c=>c.Visible&&c.Text=="Nuovo flowchart"),"New diagram action available");Check(!Walk(f).Any(c=>c.Visible&&(c.Text=="Impara"||c.Text=="Apri le lezioni")),"Learning entry points removed");Check(Walk(f).Any(c=>c.Visible&&c.Text.Contains("mamt104")),"Author visible on home");
Check(f.LoadPath(a),"Existing file opens");Check(RecentProjects.Read().SequenceEqual(new[]{a}),"Open persists recent path");Check(f.LoadPath(b),"Legacy flow opens");Check(f.LoadPath(a),"Recent can be reopened");Check(RecentProjects.Read().SequenceEqual(new[]{a,b}),"Recent order deduplicated");f.ShowHome();Pump();var home=Field<FlowchartHome>(f,"homeScreen");var row=Walk(home).OfType<HomeActionRow>().Single(r=>r.Text=="Secondo");row.PerformClick();Pump();Check(f.Document.Title=="Secondo"&&!Field<Control>(f,"homePanel").Visible,"One click opens recent project in editor");
Check(f.LoadPath(a),"Open current format before overwrite save");Field<TextBox>(f,"titleEdit").Text="Salvato dalla home";Check((bool)Call(f,"SaveDocument",false),"Save existing project succeeds");Check(DiagramIO.Load(a).Title=="Salvato dalla home"&&RecentProjects.Read()[0]==a,"Save remembers actual persisted file");
File.Delete(a);f.ShowHome();Pump();Check(!Walk(home).OfType<HomeActionRow>().Single(r=>r.Text=="Primo").Enabled,"Missing recent file shown without broken open action");
foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark,false);f.ShowHome();Pump();foreach(Control c in home.Controls)if(c.Visible)Check(c.Left>=0&&c.Right<=home.Width&&c.Bottom<=home.Height,"Home bounds: "+c.Text);using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(Point.Empty,f.Size));bitmap.Save(Path.Combine(data,"home-"+dark+".png"));}}
RecentProjects.Remember("https://invalid.example/test.frociart");RecentProjects.Remember(@"\\remote\private\a.frociart");RecentProjects.Remember(Path.Combine(data,"a.exe"));Check(RecentProjects.Read().Length==2,"Unsupported and network history paths rejected");
Check(RecentProjects.License.Contains("mamt104")&&RecentProjects.License.Contains("dell’utente"),"License credits author and preserves user-created work");f.SetDocument(new Diagram(),null,false);f.Close();}
using(var f=new MainForm(null,true)){f.ShowInTaskbar=false;f.Location=new Point(-3000,-3000);f.Show();Pump();Check(Walk(f).OfType<HomeActionRow>().Any(r=>r.Text=="Secondo"&&r.Enabled),"History restored in new application instance");f.SetDocument(new Diagram(),null,false);f.Close();}
Console.WriteLine("FLOW_HOME_PASS assertions="+count+" captures="+data);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}}
